apiVersion: v1
data:
  demo.flagd.json: |
    {
      "$schema": "https://flagd.dev/schema/v0/flags.json",
      "flags": {
        "adFailure": {
          "defaultVariant": "off",
          "description": "Fail ad service",
          "state": "ENABLED",
          "variants": {
            "off": false,
            "on": true
          }
        },
        "adHighCpu": {
          "defaultVariant": "off",
          "description": "Triggers high cpu load in the ad service",
          "state": "ENABLED",
          "variants": {
            "off": false,
            "on": true
          }
        },
        "adManualGc": {
          "defaultVariant": "off",
          "description": "Triggers full manual garbage collections in the ad service",
          "state": "ENABLED",
          "variants": {
            "off": false,
            "on": true
          }
        },
        "aiRunawayAgent": {
          "defaultVariant": "off",
          "description": "forces the agent to keep looping tool calls until it hits its recursion limit",
          "state": "ENABLED",
          "variants": {
            "off": 0,
            "on": 20
          }
        },
        "aiSlowResponse": {
          "defaultVariant": "off",
          "description": "slow LLM responses in the agent service",
          "state": "ENABLED",
          "variants": {
            "10sec": 10000,
            "5sec": 5000,
            "off": 0
          }
        },
